import * as React from "react"

import { cn } from "@/lib/utils"

/**
 * Experimental Fable UI 2 primitives.
 *
 * Ordinary React components: no AI SDK, data driver, provider, runtime,
 * global styles, or model transport required.
 */
export type Space = 0 | 1 | 2 | 3 | 4 | 6 | 8

const gaps: Record<Space, string> = {
  0: "gap-0",
  1: "gap-1",
  2: "gap-2",
  3: "gap-3",
  4: "gap-4",
  6: "gap-6",
  8: "gap-8",
}

export interface StackProps extends React.HTMLAttributes<HTMLDivElement> {
  gap?: Space
  align?: "start" | "center" | "end" | "stretch"
  direction?: "vertical" | "horizontal"
  wrap?: boolean
}

const aligns = {
  start: "items-start",
  center: "items-center",
  end: "items-end",
  stretch: "items-stretch",
}

export function Stack({
  gap = 4,
  align = "stretch",
  direction = "vertical",
  wrap = true,
  className,
  ...props
}: StackProps) {
  return (
    <div
      data-fable-ui="v2-stack"
      className={cn(
        "flex min-w-0",
        direction === "vertical" ? "flex-col" : "flex-row",
        direction === "horizontal" && wrap && "flex-wrap",
        gaps[gap],
        aligns[align],
        className
      )}
      {...props}
    />
  )
}

export interface InlineProps extends React.HTMLAttributes<HTMLDivElement> {
  gap?: Space
  align?: "start" | "center" | "end" | "stretch"
  wrap?: boolean
}

export function Inline({ gap = 3, align = "center", wrap = true, className, ...props }: InlineProps) {
  return <div data-fable-ui="v2-inline" className={cn("flex min-w-0 flex-row", gaps[gap], aligns[align], wrap && "flex-wrap", className)} {...props} />
}

export interface FableGridProps extends React.HTMLAttributes<HTMLDivElement> {
  gap?: Space
  columns?: 1 | 2 | 3 | 4
}

const gridColumns = {
  1: "grid-cols-1",
  2: "grid-cols-1 sm:grid-cols-2",
  3: "grid-cols-1 sm:grid-cols-2 lg:grid-cols-3",
  4: "grid-cols-1 sm:grid-cols-2 xl:grid-cols-4",
}

export function FableGrid({ gap = 4, columns = 2, className, ...props }: FableGridProps) {
  return <div data-fable-ui="v2-grid" className={cn("grid min-w-0", gaps[gap], gridColumns[columns], className)} {...props} />
}

export interface SurfaceProps extends React.HTMLAttributes<HTMLDivElement> {
  variant?: "plain" | "outlined" | "subtle"
  padding?: Space
}

const surfaces = {
  plain: "",
  outlined: "rounded-xl border border-border bg-card",
  subtle: "rounded-xl bg-muted/50",
}

const paddings: Record<Space, string> = {
  0: "p-0",
  1: "p-1",
  2: "p-2",
  3: "p-3",
  4: "p-4",
  6: "p-6",
  8: "p-8",
}

export function Surface({ variant = "plain", padding = 0, className, ...props }: SurfaceProps) {
  return <div data-fable-ui="v2-surface" className={cn("min-w-0", surfaces[variant], paddings[padding], className)} {...props} />
}

export interface SectionProps extends React.HTMLAttributes<HTMLElement> {
  gap?: Space
}

export function Section({ gap = 4, className, ...props }: SectionProps) {
  return <section data-fable-ui="v2-section" className={cn("flex min-w-0 flex-col", gaps[gap], className)} {...props} />
}

export interface FableTextProps extends React.HTMLAttributes<HTMLParagraphElement> {
  tone?: "default" | "muted"
  size?: "sm" | "base" | "lg"
}

const textSizes = { sm: "text-sm", base: "text-base", lg: "text-lg" }

export function FableText({ tone = "default", size = "base", className, ...props }: FableTextProps) {
  return <p data-fable-ui="v2-text" className={cn("leading-relaxed", textSizes[size], tone === "muted" && "text-muted-foreground", className)} {...props} />
}

export function isSafeLocalAssetPath(value: string): boolean {
  return (
    value.startsWith("/") &&
    !value.startsWith("//") &&
    !value.includes("\\") &&
    !value.includes("..") &&
    !/[?#:]/.test(value) &&
    /^\/[A-Za-z0-9_./-]+\.(?:avif|gif|jpe?g|png|svg|webp)$/i.test(value)
  )
}

import * as React from "react"

import { cn } from "@/lib/utils"

export type FableTextLevel = "body" | "heading" | "caption"
export type FableTextMark = "plain" | "strong" | "emphasis" | "code"

export interface FableRichTextSpan {
  text: string
  mark: FableTextMark
}

export interface FableTypographyProps {
  as?: "p" | "h2" | "h3" | "span"
  level?: FableTextLevel
  className?: string
  children: React.ReactNode
}

const levelStyles: Record<FableTextLevel, string> = {
  body: "text-[15px] leading-7 text-foreground",
  heading: "text-xl font-semibold leading-tight tracking-[-0.03em] sm:text-2xl",
  caption: "text-sm leading-6 text-muted-foreground",
}

const MarkedSpan = ({ span }: { span: FableRichTextSpan }) => {
  switch (span.mark) {
    case "strong":
      return <strong className="font-semibold text-foreground">{span.text}</strong>
    case "emphasis":
      return <em>{span.text}</em>
    case "code":
      return (
        <code className="rounded bg-muted px-1.5 py-0.5 font-mono text-[0.9em]">
          {span.text}
        </code>
      )
    default:
      return <>{span.text}</>
  }
}

export function FableTypography({
  as = "p",
  level = "body",
  className,
  children,
}: FableTypographyProps) {
  const Component = as
  return (
    <Component className={cn("min-w-0", levelStyles[level], className)}>
      {children}
    </Component>
  )
}

export interface FableRichTextProps {
  spans: FableRichTextSpan[]
  className?: string
}

export function FableRichText({ spans, className }: FableRichTextProps) {
  return (
    <p className={cn("max-w-prose text-[15px] leading-7 text-muted-foreground", className)}>
      {spans.map((span, index) => (
        <MarkedSpan key={`${span.mark}-${index}`} span={span} />
      ))}
    </p>
  )
}

export const MAX_FABLE_RICH_CONTENT_BLOCKS = 12
export const MAX_FABLE_RICH_CONTENT_SPANS = 16
export const MAX_FABLE_RICH_CONTENT_LIST_ITEMS = 12
export const MAX_FABLE_RICH_CONTENT_TEXT_CHARS = 240
export const MAX_FABLE_RICH_CONTENT_CODE_CHARS = 4000
export const MAX_FABLE_RICH_CONTENT_TOTAL_CHARS = 8000
export const MAX_FABLE_RICH_CONTENT_ELEMENT_BYTES = 12 * 1024
export const MAX_FABLE_HOST_LINKS = 24
export const MAX_FABLE_LINK_HREF_CHARS = 512

const LOCAL_LINK_BASE = "https://fable-ui.invalid"

export interface FableLinkTarget {
  href: string
  label: string
}

export type FableLinkCatalog = Readonly<Record<string, FableLinkTarget>>

export interface SafeFableLinkHref {
  href: string
  hostLabel: string
}

/** Accepts host-owned same-origin paths and HTTPS URLs, never model-authored URLs. */
export function parseSafeFableLinkHref(
  value: unknown
): SafeFableLinkHref | null {
  if (
    typeof value !== "string" ||
    value.length === 0 ||
    value.length > MAX_FABLE_LINK_HREF_CHARS ||
    /[\\\s\u0000-\u001f\u007f]/u.test(value)
  ) {
    return null
  }

  if (value.startsWith("/")) {
    if (value.startsWith("//")) return null

    try {
      const url = new URL(value, LOCAL_LINK_BASE)
      // URL parsing normalizes dot segments. Inputs such as `/.//host/path`
      // become `//host/path`, which browsers interpret as a protocol-relative
      // URL when used as an anchor href.
      if (url.origin !== LOCAL_LINK_BASE || url.pathname.startsWith("//")) {
        return null
      }
      return {
        href: `${url.pathname}${url.search}${url.hash}`,
        hostLabel: "this site",
      }
    } catch {
      return null
    }
  }

  if (!/^https:\/\//i.test(value)) return null

  try {
    const url = new URL(value)
    if (
      url.protocol !== "https:" ||
      !url.hostname ||
      url.username ||
      url.password
    ) {
      return null
    }
    return { href: url.href, hostLabel: url.host }
  } catch {
    return null
  }
}

export function isSafeFableLinkHref(value: unknown): value is string {
  return parseSafeFableLinkHref(value) !== null
}

import * as React from "react"

import { cn } from "@/lib/utils"
import {
  parseSafeFableLinkHref,
  type FableLinkCatalog,
} from "./rich-content-utils"
import type { FableTextMark } from "./typography"

export interface FableRichContentTextSpan {
  type: "text"
  text: string
  mark: FableTextMark
}

export interface FableRichContentLinkRef {
  type: "link"
  linkId: string
}

export type FableRichContentInline =
  FableRichContentTextSpan | FableRichContentLinkRef

export type FableRichContentBlock =
  | { type: "paragraph"; spans: FableRichContentInline[] }
  | { type: "heading"; level: 2 | 3; spans: FableRichContentInline[] }
  | {
      type: "list"
      ordered: boolean
      items: FableRichContentInline[][]
    }
  | { type: "quote"; spans: FableRichContentInline[] }
  | { type: "code"; code: string; language?: string }

export interface FableRichContentProps {
  blocks: FableRichContentBlock[]
  links?: FableLinkCatalog
  className?: string
}

function renderInline(
  spans: FableRichContentInline[],
  links: FableLinkCatalog
): React.ReactNode[] {
  return spans.map((span, index) => {
    const key = `${span.type}-${index}`

    if (span.type === "link") {
      const target = Object.hasOwn(links, span.linkId)
        ? links[span.linkId]
        : undefined
      const destination = target ? parseSafeFableLinkHref(target.href) : null

      if (!target?.label.trim() || !destination) {
        return (
          <span key={key} className="text-muted-foreground">
            Link unavailable
          </span>
        )
      }

      return (
        <a
          key={key}
          href={destination.href}
          className="font-medium text-primary underline decoration-primary/40 underline-offset-4 transition-colors hover:decoration-primary focus-visible:rounded-sm focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none"
        >
          {target.label}
          <span
            aria-hidden="true"
            className="ms-1 text-xs font-normal text-muted-foreground"
          >
            ({destination.hostLabel})
          </span>
        </a>
      )
    }

    switch (span.mark) {
      case "strong":
        return (
          <strong key={key} className="font-semibold text-foreground">
            {span.text}
          </strong>
        )
      case "emphasis":
        return <em key={key}>{span.text}</em>
      case "code":
        return (
          <code
            key={key}
            className="rounded bg-muted px-1.5 py-0.5 font-mono text-[0.9em]"
          >
            {span.text}
          </code>
        )
      default:
        return <React.Fragment key={key}>{span.text}</React.Fragment>
    }
  })
}

export function FableRichContent({
  blocks,
  links = {},
  className,
}: FableRichContentProps) {
  return (
    <div className={cn("min-w-0 space-y-4", className)}>
      {blocks.map((block, index) => {
        const key = `${block.type}-${index}`

        switch (block.type) {
          case "paragraph":
            return (
              <p
                key={key}
                className="max-w-prose text-[15px] leading-7 text-muted-foreground"
              >
                {renderInline(block.spans, links)}
              </p>
            )
          case "heading": {
            const Heading = block.level === 2 ? "h2" : "h3"
            return (
              <Heading
                key={key}
                className={cn(
                  "max-w-prose font-semibold tracking-[-0.02em] text-foreground",
                  block.level === 2
                    ? "text-lg sm:text-xl"
                    : "text-base sm:text-lg"
                )}
              >
                {renderInline(block.spans, links)}
              </Heading>
            )
          }
          case "list": {
            const List = block.ordered ? "ol" : "ul"
            return (
              <List
                key={key}
                className={cn(
                  "max-w-prose space-y-1 ps-6 text-[15px] leading-7 text-muted-foreground marker:text-muted-foreground",
                  block.ordered ? "list-decimal" : "list-disc"
                )}
              >
                {block.items.map((item, itemIndex) => (
                  <li key={`item-${itemIndex}`}>{renderInline(item, links)}</li>
                ))}
              </List>
            )
          }
          case "quote":
            return (
              <blockquote
                key={key}
                className="max-w-prose border-s-2 border-border ps-4 text-[15px] leading-7 text-muted-foreground"
              >
                {renderInline(block.spans, links)}
              </blockquote>
            )
          case "code":
            return (
              <figure
                key={key}
                className="max-w-full min-w-0 overflow-hidden rounded-xl border border-border bg-muted/30"
              >
                {block.language ? (
                  <figcaption className="border-b border-border/70 px-4 py-2 text-xs font-medium text-muted-foreground">
                    {block.language}
                  </figcaption>
                ) : null}
                <pre
                  tabIndex={0}
                  aria-label={
                    block.language
                      ? `${block.language} code sample`
                      : "Code sample"
                  }
                  className="max-w-full overflow-x-auto p-4 text-xs leading-5 focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none focus-visible:ring-inset"
                >
                  <code className="font-mono whitespace-pre">{block.code}</code>
                </pre>
              </figure>
            )
        }
      })}
    </div>
  )
}

import { useId } from "react"

import { cn } from "@/lib/utils"

export type FableMetricFormat = "number" | "currency" | "percent"

export interface FableMetricCardProps {
  label: string
  value: number
  format: FableMetricFormat
  currency?: string
  unit?: string
  locale?: string
  note?: string
  className?: string
}

function formatValue({
  value,
  format,
  currency,
  locale,
}: Pick<FableMetricCardProps, "value" | "format" | "currency" | "locale">) {
  const safeLocale = locale || "en"

  if (format === "currency" && currency) {
    return new Intl.NumberFormat(safeLocale, {
      style: "currency",
      currency,
      maximumFractionDigits: 0,
    }).format(value)
  }

  if (format === "percent") {
    return new Intl.NumberFormat(safeLocale, {
      style: "percent",
      maximumFractionDigits: 1,
    }).format(value / 100)
  }

  return new Intl.NumberFormat(safeLocale, {
    maximumFractionDigits: Number.isInteger(value) ? 0 : 1,
  }).format(value)
}

export function FableMetricCard({
  label,
  value,
  format,
  currency,
  unit,
  locale,
  note,
  className,
}: FableMetricCardProps) {
  const labelId = useId()

  return (
    <article
      aria-labelledby={labelId}
      className={cn(
        "min-w-0 rounded-2xl border border-border/80 bg-card p-4 shadow-sm shadow-black/[0.025] sm:p-5",
        className
      )}
    >
      <p id={labelId} className="text-sm font-medium text-muted-foreground">
        {label}
      </p>
      <div className="mt-3 flex min-w-0 flex-wrap items-baseline gap-x-2 gap-y-1">
        <p className="max-w-full truncate text-3xl font-semibold leading-none tracking-[-0.04em] tabular-nums sm:text-4xl">
          {formatValue({ value, format, currency, locale })}
        </p>
        {unit ? <span className="text-sm text-muted-foreground">{unit}</span> : null}
      </div>
      {note ? <p className="mt-3 text-xs leading-5 text-muted-foreground">{note}</p> : null}
    </article>
  )
}

import { useId } from "react"

import { cn } from "@/lib/utils"

export interface FableChartPoint {
  label: string
  value: number
}

export interface FableBarChartProps {
  label: string
  points: FableChartPoint[]
  format?: "number" | "currency" | "percent"
  currency?: string
  locale?: string
  className?: string
}

function formatValue(
  value: number,
  format: FableBarChartProps["format"],
  currency: string | undefined,
  locale: string | undefined
) {
  const safeLocale = locale || "en"
  if (format === "currency" && currency) {
    return new Intl.NumberFormat(safeLocale, {
      style: "currency",
      currency,
      maximumFractionDigits: 0,
    }).format(value)
  }
  if (format === "percent") {
    return new Intl.NumberFormat(safeLocale, {
      style: "percent",
      maximumFractionDigits: 1,
    }).format(value / 100)
  }
  return new Intl.NumberFormat(safeLocale, {
    maximumFractionDigits: Number.isInteger(value) ? 0 : 1,
  }).format(value)
}

export function FableBarChart({
  label,
  points,
  format = "number",
  currency,
  locale,
  className,
}: FableBarChartProps) {
  const width = 640
  const height = 220
  const paddingLeft = 56
  const paddingRight = 18
  const paddingTop = 18
  const paddingBottom = 30
  const chartHeight = height - paddingTop - paddingBottom
  const dataMin = Math.min(0, ...points.map((point) => point.value))
  const dataMax = Math.max(0, ...points.map((point) => point.value))
  const hasRange = dataMax !== dataMin
  const min = hasRange ? dataMin : 0
  const max = hasRange ? dataMax : 1
  const range = max - min
  const yFor = (value: number) => paddingTop + ((max - value) / range) * chartHeight
  const zeroY = yFor(0)
  const ticks = hasRange
    ? [...new Set([max, (max + min) / 2, min])]
    : [0]
  const innerWidth = width - paddingLeft - paddingRight
  const slotWidth = points.length > 0 ? innerWidth / points.length : 0
  const barWidth = Math.min(44, slotWidth * 0.48)
  const descriptionId = useId()

  return (
    <figure className={cn("min-w-0 rounded-2xl border border-border/80 bg-card p-4 shadow-sm shadow-black/[0.025] sm:p-5", className)}>
      <figcaption className="text-sm font-semibold tracking-[-0.01em]">{label}</figcaption>
      <svg
        className="mt-5 block h-auto w-full overflow-visible text-muted-foreground"
        viewBox={`0 0 ${width} ${height}`}
        role="img"
        aria-labelledby={descriptionId}
      >
        <title id={descriptionId}>{label}</title>
        {ticks.map((tick) => {
          const y = yFor(tick)
          return (
            <g key={tick}>
              <line
                x1={paddingLeft}
                x2={width - paddingRight}
                y1={y}
                y2={y}
                stroke="currentColor"
                strokeOpacity={tick === 0 ? "0.22" : "0.1"}
                strokeWidth="1"
              />
              <text
                x={paddingLeft - 8}
                y={y + 4}
                textAnchor="end"
                className="fill-current text-[11px] tabular-nums"
              >
                {formatValue(tick, format, currency, locale)}
              </text>
            </g>
          )
        })}
        {points.map((point, index) => {
          const valueY = yFor(point.value)
          const barY = Math.min(valueY, zeroY)
          const barHeight = Math.max(Math.abs(zeroY - valueY), 2)
          const x = paddingLeft + slotWidth * index + (slotWidth - barWidth) / 2
          const labelX = paddingLeft + slotWidth * index + slotWidth / 2

          return (
            <g key={`${point.label}-${index}`}>
              <rect
                x={x}
                y={barY}
                width={barWidth}
                height={barHeight}
                rx="7"
                fill="var(--chart-2)"
                fillOpacity="0.82"
              />
              <text
                x={labelX}
                y={height - 4}
                textAnchor="middle"
                className="fill-current text-[12px]"
              >
                {point.label}
              </text>
            </g>
          )
        })}
      </svg>
      <ul className="sr-only">
        {points.map((point, index) => (
          <li key={`${point.label}-${index}`}>
            {point.label}: {formatValue(point.value, format, currency, locale)}
          </li>
        ))}
      </ul>
    </figure>
  )
}

import { useId } from "react"

import { cn } from "@/lib/utils"

export interface FableFilterOption {
  label: string
  value: string
}

export interface FableFilterBarProps {
  label: string
  value: string
  options: FableFilterOption[]
  onValueChange: (value: string) => void
  className?: string
}

export function FableFilterBar({
  label,
  value,
  options,
  onValueChange,
  className,
}: FableFilterBarProps) {
  const selectId = useId()

  return (
    <div className={cn("flex min-w-0 flex-col gap-2 sm:flex-row sm:items-center sm:justify-between", className)}>
      <label htmlFor={selectId} className="text-sm font-medium text-foreground">
        {label}
      </label>
      <select
        id={selectId}
        value={value}
        onChange={(event) => onValueChange(event.currentTarget.value)}
        className="h-10 w-full min-w-0 rounded-xl border border-input bg-background px-3 text-sm text-foreground shadow-sm outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring sm:w-auto sm:min-w-44"
      >
        {options.map((option) => (
          <option key={option.value} value={option.value}>
            {option.label}
          </option>
        ))}
      </select>
    </div>
  )
}

import Image from "next/image"

import { isSafeLocalAssetPath } from "./asset-utils"

export interface FableMediaImageProps {
  src: string
  alt: string
  decorative?: boolean
  className?: string
}

export function FableMediaImage({
  src,
  alt,
  decorative = false,
  className,
}: FableMediaImageProps) {
  if (!isSafeLocalAssetPath(src)) {
    return (
      <div
        role="status"
        className={className ?? "grid aspect-[16/9] min-w-0 place-items-center rounded-xl bg-muted text-sm text-muted-foreground"}
      >
        Image unavailable
      </div>
    )
  }

  return (
    <Image
      src={src}
      alt={decorative ? "" : alt}
      width={1280}
      height={720}
      unoptimized
      className={className ?? "h-auto w-full rounded-xl object-cover"}
    />
  )
}
